// The tables generated by generate_fonts.py (soft_fonts.cpp). Who uses and
// tab5_ui.cpp - the rest of the system is just tab5_texto()/tab5_fonte_corpo().
#pragma once
#include <stdint.h>

typedef struct {
  int            height;   // height of line in px (its d.fontHeight())
  const uint8_t* data;    // the entire VLW file, in flash
  uint32_t       tamanho;
} fonte_suave_t;

extern const fonte_suave_t FONTES_CORPO[];
extern const int           FONTES_CORPO_N;
extern const fonte_suave_t FONTES_NEGRITO[];
extern const int           FONTES_NEGRITO_N;
